package com.lyra.studio; import com.google.appinventor.components.annotations.*; import com.google.appinventor.components.common.*; import com.google.appinventor.components.runtime.*; import android.app.Activity; import android.view.WindowManager; @DesignerComponent(version = 1, description = "Extensão para adaptar o WebViewer ao teclado virtual, evitando que o conteúdo seja coberto.", category = ComponentCategory.EXTENSION, nonVisible = true, iconName = "images/extension.png") @SimpleObject(external = true) public class KeyboardAdaptiveWebViewer extends AndroidNonvisibleComponent { private Activity activity; public KeyboardAdaptiveWebViewer(ComponentContainer container) { super(container.$form()); this.activity = container.$context(); } @SimpleFunction(description = "Ajusta o layout da tela para redimensionar quando o teclado virtual aparecer, protegendo o WebViewer.") public void EnableKeyboardAdaptation() { if (activity != null) { activity.runOnUiThread(new Runnable() { @Override public void run() { /* Define o modo do teclado para ajustar/redimensionar a tela */ activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE); } }); } } @SimpleFunction(description = "Desativa a adaptação do teclado, retornando ao comportamento padrão.") public void DisableKeyboardAdaptation() { if (activity != null) { activity.runOnUiThread(new Runnable() { @Override public void run() { /* Retorna ao modo padrão (geralmente pan ou unspecified) */ activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_UNSPECIFIED); } }); } } }